package targetdraft

import (
	"bytes"
	"fmt"
	"io"
	"sort"
	"strings"
)

// Harness-only measurement layer. Nothing here is read by the generator: the
// generated bytes of any input are the same with or without this file.

// CauseHalfBVsAttestless is informational: the shipped file is exactly half A
// (onboarding target without attest and exclusions) while the entry compared
// half B. It never counts as strict and is not a generator defect.
const CauseHalfBVsAttestless = "half-b-vs-attestless"

// m7Escalates reports whether a plain run that ended in these typed stops runs
// again with inference. Without escalateAny: only the listed codes, and a mix
// with an unlisted code does not. With escalateAny: any typed stop of the
// generator, except the harness's own mirror-missing (a rerun cannot help).
func m7Escalates(e btEntry, stops []string) bool {
	if len(stops) == 0 {
		return false
	}
	for _, c := range stops {
		if e.EscalateAny {
			if c == StopMirrorMissing {
				return false
			}
			continue
		}
		if !containsString(escalateStops, c) {
			return false
		}
	}
	return true
}

// m7Run runs one entry and adds the report-only fields.
func m7Run(e btEntry, base, mirrors string, open func(string) Source) btRun {
	if e.EscalateAny && !e.Escalate {
		return btRun{res: BacktestResult{Slug: e.Slug, Class: ClassHarnessError, Error: "escalateAny requires escalate"}}
	}
	r := runEntry(e, base, mirrors, open)
	r.res.Half = e.Half
	switch r.res.Class {
	case ClassReproduced, ClassReproducedCircular, ClassReproducedOracle:
	default:
		if r.gen != nil {
			if d, err := decodeDoc(r.gen); err == nil {
				r.res.GeneratedMinFrom = d.Target.MinFrom
			}
		}
	}
	return r
}

// m7Subjects lists "code:subject" for every stop that names a subject, sorted.
func m7Subjects(stops []Stop) []string {
	var out []string
	for _, s := range stops {
		if s.Subject != "" {
			out = append(out, s.Code+":"+s.Subject)
		}
	}
	sort.Strings(out)
	return out
}

// m7Plain records the plain run's stops on an escalated result; only for
// escalateAny, so the default report is unchanged.
func m7Plain(res *BacktestResult, plain BacktestResult, e btEntry) {
	if e.EscalateAny {
		res.PlainStops, res.PlainStopSubjects = plain.Stops, plain.StopSubjects
	}
}

// m7Cause returns CauseHalfBVsAttestless when half B was compared, differs, and
// the shipped bytes are exactly half A; otherwise the cause as it was.
func m7Cause(e btEntry, gen *Result, expected []byte, cause string) string {
	if e.Half == "B" && gen != nil && !bytes.Equal(gen.B, expected) && bytes.Equal(gen.A, expected) {
		return CauseHalfBVsAttestless
	}
	return cause
}

// m7Histogram fills the per-class tally: class, cause, final typed stops and,
// for an escalated entry, its second-level stops and the plain stop it came from.
func m7Histogram(rep *BacktestReport) {
	h := map[string]int{}
	for _, r := range rep.Results {
		h["class:"+r.Class]++
		if r.Cause != "" {
			h["cause:"+r.Cause]++
		}
		esc := r.Escalated != nil && *r.Escalated
		for _, s := range r.Stops {
			if esc {
				h["second-level-stop:"+s]++
			} else {
				h["stop:"+s]++
			}
		}
		if esc && r.PlainStop != "" {
			h["escalated-from:"+r.PlainStop]++
		}
	}
	if len(h) > 0 {
		rep.Histogram = h
	}
}

// m7LineTail is appended to the human line of one entry.
func m7LineTail(r BacktestResult) string {
	var t string
	if r.Half != "" {
		t += " half=" + r.Half
	}
	if r.GeneratedMinFrom != "" {
		t += " generatedMinFrom=" + r.GeneratedMinFrom
	}
	if len(r.StopSubjects) > 0 {
		t += " stopSubjects=" + strings.Join(r.StopSubjects, ";")
	}
	if len(r.PlainStops) > 0 {
		t += " plainStops=" + strings.Join(r.PlainStops, ",")
	}
	if len(r.PlainStopSubjects) > 0 {
		t += " plainStopSubjects=" + strings.Join(r.PlainStopSubjects, ";")
	}
	return t
}

// m7PrintSummary prints the strict number apart from every reviewed-input
// number, then the histogram. Oracle and circular results are never strict.
func m7PrintSummary(w io.Writer, rep BacktestReport) {
	fmt.Fprintf(w, "strict (no oracle)=%d/%d\n", rep.Reproduced, rep.N)
	fmt.Fprintf(w, "oracle-assisted=%d/%d\n", rep.OracleRepro, rep.N)
	var keys []string
	for k := range rep.Histogram {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var parts []string
	for _, k := range keys {
		parts = append(parts, fmt.Sprintf("%s=%d", k, rep.Histogram[k]))
	}
	if len(parts) > 0 {
		fmt.Fprintln(w, "HISTOGRAM "+strings.Join(parts, " "))
	}
}
